const root = $('Single Build Prompt Context').first().json;
const raw = $json.choices?.[0]?.message?.content ?? "{}";
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) {
  parsed = { final_prompt: raw, negative_prompt: "", title_hint: "Jewellery AI Output" };
}
const fallbackNegative = [
  "SKU code","product number","serial number","barcode","label","price tag",
  "letters in image","alphabet in frame","numbers","random text","text covering jewellery",
  "monogram","two-letter monogram","single letter graphic","brand initials","signature mark",
  "AI watermark","corner watermark text","typography badge","decorative letters","embedded text logo",
  "wrong logo placement","logo on jewellery","blurry","low detail","distorted jewellery",
  "changed jewellery design","altered gemstone layout","changed metal tone","extra jewellery pieces",
  "duplicate accessories","warped fingers","broken anatomy","unrealistic gemstones",
  "altered product shape","low-resolution","cropped product","hidden jewellery","cluttered frame",
  "cheap look","overexposed metal","fake reflections","extra hands","deformed face",
  "AI face glitch","uncanny valley face","deformed stones","asymmetric prongs","fused gold links",
  "melted metal","plasticky finish","cheap toy look","painted-on gemstones",
  "flat lighting on gold","dull metal sheen","dirty marks","smudges","fingerprints",
  "monochromatic Bollywood fair skin","over-smoothed plastic skin","AI stock photo look",
  "generic AI styling","glass-like pearls","chrome-like pearls","flat white circle diamond",
  "painted enamel","smudged kundan"
].join(", ");
return [{
  json: {
    ...root,
    final_prompt:    parsed.final_prompt    || raw,
    negative_prompt: parsed.negative_prompt || fallbackNegative,
    title_hint:      parsed.title_hint      || "Jewellery AI Output"
  }
}];

const rawSize = String($json.output_size || "").toLowerCase().replace(/\s+/g, "");
let falSize = "square_hd";
if (rawSize.includes("1080x1920") || rawSize.includes("9:16") || rawSize.includes("mobile") || rawSize.includes("story") || rawSize.includes("reel")) falSize = "portrait_9_16";
else if (rawSize.includes("1080x1350") || rawSize.includes("4:5") || rawSize.includes("portrait")) falSize = "portrait_4_5";
else if (rawSize.includes("1080x1080") || rawSize.includes("square") || rawSize.includes("1:1")) falSize = "square_hd";
return [{ json: { ...$json, fal_size: falSize } }];

const root = $('Single Map Size').first().json;
const images = $json.images || $json.data?.images || [];
const output_urls = images.map(it => it.url || it.image?.url || it.image_url).filter(Boolean);
if (!output_urls.length) throw new Error("No output URLs returned from FAL");
const firstUrl = output_urls[0];
const ext = firstUrl.match(/\.(\w+)(?:\?|$)/)?.[1]?.toLowerCase() || 'png';
const objectPath = `jewellery-outputs/${root.user_id || 'guest'}/${Date.now()}-${root.generation_id}.${ext}`;
return [{ json: { ...root, fal_output_urls: output_urls, fal_output_url: firstUrl, object_path: objectPath, output_mime: ext === 'jpg' || ext === 'jpeg' ? 'image/jpeg' : 'image/png' } }];

const meta = $('Single Normalize Results').first().json;
const publicUrl = `${$env.SUPABASE_URL}/storage/v1/object/public/designs/${meta.object_path}`;
return [{ json: { ...meta, output_url: publicUrl } }];

const p = $json.payload;
const shared = p.shared_settings || {};
return (p.items || []).map((item) => ({
  json: {
    generation_id: item.generation_id,
    user_id: p.user_id,
    batch_id: p.batch_id || null,
    generation_mode: "bulk",
    source_image_url: item.source_image_url || shared.source_image_url,
    original_name: item.original_name || "",
    ...shared,
    source_image_url_shared: shared.source_image_url,
  }
}));

const p = $json;
const brand = p.brand_details || {};
const brandLine = [
  brand.company_name ? `Company: ${brand.company_name}` : "",
  brand.website      ? `Website: ${brand.website}`      : "",
  brand.phone        ? `Phone/WhatsApp: ${brand.phone}` : "",
  brand.address      ? `Address: ${brand.address}`      : ""
].filter(Boolean).join(" | ");
const moreJewellery = Array.isArray(p.more_jewellery) && p.more_jewellery.length ? p.more_jewellery.join(", ") : "";
const jewelleryLabel = p.custom_jewellery ? p.custom_jewellery : (moreJewellery ? `${p.jewellery_type} (${moreJewellery})` : p.jewellery_type);
return [{
  json: {
    ...p,
    prompt_context: {
      source_image_url:   p.source_image_url,
      model_image_url:    p.model_image_url || "",
      has_uploaded_model: Boolean(p.has_uploaded_model),
      jewellery_type:     jewelleryLabel,
      jewellery_notes:    p.jewellery_notes || "",
      output_type:        p.output_type   || "Luxury Studio",
      shoot_style:        p.shoot_style   || "Luxury Studio",
      model_type:         p.model_type    || "No Model",
      pose:               p.pose          || "Auto Pose",
      model_look:         p.model_look    || "Indian Model",
      face_expression:    p.face_expression || "Soft Smile",
      model_notes:        p.model_notes   || "",
      accessories:        p.accessories   || "No Accessories",
      camera_angle:       p.camera_angle  || "Auto Angle",
      output_size:        p.output_size   || "Square 1080x1080",
      output_quality:     p.output_quality|| "Premium",
      brand_details:      brandLine,
      brand_logo_url:     brand.logo_url || "",
      has_brand_text:     Boolean(p.has_brand_text),
      reserve_bottom_strip: Boolean(p.reserve_bottom_strip),
      af_watermark:       Boolean(p.af_watermark),
      reserve_second_corner: Boolean(p.reserve_second_corner ?? p.af_watermark),
      custom_instruction: p.custom_instruction || ""
    }
  }
}];

